selected.compute:
options = read('/input/options')
result = []
for n in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, n):
        ids = [item['id'] for item in group]
        if valid(ids):
            result = ids
            break
    if result:
        break

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
    if valid(selection):
        delivery = status('report')
        if delivery == 'not_sent':
            send('report', 'team', selection)
else:
    if valid(result):
        write('/output/selection', result)
        delivery = status('report')
        if delivery == 'not_sent':
            send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
